<script lang="ts">
  import { invoke } from '@tauri-apps/api/core';
  import { open, save } from '@tauri-apps/plugin-dialog';
  import AiEditor from './components/AiEditor.svelte';
  import ValveEditor from './components/ValveEditor.svelte';
  import NetworkEditor from './components/NetworkEditor.svelte';
  import BehaviorGraph from './components/BehaviorGraph.svelte';
  import AnimationGraph from './components/AnimationGraph.svelte';
  import ReferenceBrowser from './components/ReferenceBrowser.svelte';
  import type { DocumentSnapshot, ExportResult, LibrarySnapshot, MissionSummary, WorkspaceDocument, WorkspaceSnapshot } from './types';
  import { DEFAULT_AI_LAYOUT, type AiLayout } from './ai-layout';
  import { documentOf, pairList } from './workspace';

  let { aiLayout=DEFAULT_AI_LAYOUT }: { aiLayout?:AiLayout } = $props();

  let library=$state<LibrarySnapshot|null>(null);let workspace=$state<WorkspaceSnapshot|null>(null);let legacy=$state<DocumentSnapshot|null>(null);
  let mode=$state<'ai'|'behavior'|'animations'|'valves'|'networks'|'references'>('ai');let busy=$state(false);let message=$state('Choose a MechWarrior 3 folder or open a Reader file.');let attached=$state<string[]>([]);let networkFocus=$state('');let refreshTimer:number|undefined;let refreshGeneration=0;let lastRoot=$state(localStorage.getItem('mech-reader-studio:last-root')??'');let missionCollapsed=$state(localStorage.getItem('mech-reader-studio:mission-sidebar')==='collapsed');
  const dirname=(path:string)=>path.slice(0,Math.max(path.lastIndexOf('\\'),path.lastIndexOf('/')));
  function missionActive(mission:MissionSummary){return workspace?.selectedMission.toLowerCase()===mission.path.toLowerCase()}
  async function loadRoot(path:string){busy=true;try{library=await invoke<LibrarySnapshot>('scan_game_root',{rootPath:path});workspace=null;legacy=null;attached=[];lastRoot=path;localStorage.setItem('mech-reader-studio:last-root',path);message=`Indexed ${library.missions.length} mission Readers`;if(!library.missions.length)message='No mission Reader archives were found.'}catch(error){message=String(error)}finally{busy=false}}
  async function chooseRoot(){const path=await open({directory:true,multiple:false});if(path)await loadRoot(path)}
  async function openMission(mission:MissionSummary){if(!library)return;busy=true;try{workspace=await invoke<WorkspaceSnapshot>('open_workspace',{rootPath:library.rootPath,missionPath:mission.path,additionalPaths:attached});legacy=null;mode='ai';message=`Loaded ${mission.name} with ${workspace.archives.length} Reader layers`}catch(error){message=String(error)}finally{busy=false}}
  async function attachReader(){if(!workspace)return;const path=await open({multiple:false,filters:[{name:'Reader archive',extensions:['zbd']}]});if(!path)return;attached=[...new Set([...attached,path])];busy=true;try{workspace=await invoke<WorkspaceSnapshot>('open_workspace',{rootPath:workspace.rootPath,missionPath:workspace.selectedMission,additionalPaths:attached});message=`Attached ${path}`}catch(error){message=String(error)}finally{busy=false}}
  async function openDirect(){const path=await open({multiple:false,filters:[{name:'MW3 Reader data',extensions:['zbd','zrd','json']}]});if(!path)return;busy=true;try{if(path.toLowerCase().endsWith('.zbd')){workspace=await invoke<WorkspaceSnapshot>('open_workspace',{rootPath:dirname(path),missionPath:path,additionalPaths:[]});legacy=null;library=null;message=`Opened ${path}`}else{legacy=await invoke<DocumentSnapshot>('open_document',{path});const root=[] as import('./types').Json[];for(const vehicle of legacy.vehicles)root.push(vehicle.name,vehicle.record);const document:WorkspaceDocument={id:'legacy:aiv',archiveId:'legacy',entryName:'aiv.zrd',kind:'aiv',layer:'mission',root};workspace={sessionId:0,rootPath:dirname(path),selectedMission:path,archives:[{id:'legacy',path,relativePath:path.split(/[\\/]/).pop()??path,layer:'mission',locked:false}],documents:[document],references:[],diagnostics:legacy.warnings.map(w=>({severity:'warning',code:'legacy-warning',message:w})),valveGraph:{scopeKey:'',nodes:[],edges:[],channels:[],hosts:[],diagnostics:[]}};library=null;message=`Opened ${path}`}mode='ai'}catch(error){message=String(error)}finally{busy=false}}
  async function refreshReferences(generation:number){if(!workspace||workspace.sessionId===0||generation!==refreshGeneration)return;try{const refreshed=await invoke<WorkspaceSnapshot>('refresh_workspace',{snapshot:workspace});if(generation===refreshGeneration)workspace=refreshed}catch(error){message=String(error)}}
  function changed(){if(!workspace)return;workspace={...workspace,documents:[...workspace.documents]};if(workspace.sessionId===0)return;refreshGeneration++;const generation=refreshGeneration;if(refreshTimer)clearTimeout(refreshTimer);refreshTimer=window.setTimeout(()=>refreshReferences(generation),300)}
  function navigate(kind:string,name:string){if(kind==='region'){networkFocus=name;mode='networks'}}
  function navigateGraph(node:import('./types').ValveGraphNode){const document=workspace?.documents.find(item=>item.id===node.binding.documentId);if(document?.kind==='aiv')mode='ai';else if(document?.kind==='valves')mode='valves';else if(document?.kind==='network'||document?.kind==='region'){networkFocus=document.entryName.replace(/\.zrd$/i,'');mode='networks'}else{mode='references';message=`${node.binding.entryName} has no form editor yet; opened References at its structured graph binding.`}}
  function graphWorkspace(next:WorkspaceSnapshot){workspace=next}
  async function unlock(archiveId:string){if(!workspace)return;const archive=workspace.archives.find(a=>a.id===archiveId);if(archive){archive.locked=false;workspace={...workspace,archives:[...workspace.archives]};if(workspace.sessionId!==0)try{workspace=await invoke<WorkspaceSnapshot>('refresh_workspace',{snapshot:workspace})}catch(error){message=String(error);return}message=`Unlocked ${archive.relativePath} for this export workspace`}}
  function toggleMissionSidebar(){missionCollapsed=!missionCollapsed;localStorage.setItem('mech-reader-studio:mission-sidebar',missionCollapsed?'collapsed':'expanded')}
  async function exportChanges(){if(!workspace)return;if(workspace.sessionId===0){if(!legacy)return;const document=workspace.documents[0];legacy.vehicles=[];const root=pairList(document.root);for(let i=0;i+1<root.length;i+=2)if(typeof root[i]==='string'&&Array.isArray(root[i+1]))legacy.vehicles.push({id:`v${i/2}`,name:root[i] as string,record:root[i+1] as import('./types').Json[]});const ext=legacy.sourceKind==='zrd'?'zrd':'json';const path=await save({defaultPath:`aiv-edited.${ext}`,filters:[{name:'Output',extensions:[ext]}]});if(!path)return;busy=true;try{await invoke('save_document',{path,snapshot:legacy});message=`Saved ${path}`}catch(error){message=String(error)}finally{busy=false}return}const folder=await open({directory:true,multiple:false});if(!folder)return;busy=true;try{const result=await invoke<ExportResult>('export_workspace',{exportRoot:folder,snapshot:workspace});message=result.files.length?`Exported ${result.changedDocuments} document(s) in ${result.files.length} Reader archive(s)`:'Nothing changed; no archives were written.'}catch(error){message=String(error)}finally{busy=false}}
  const aiDocument=()=>workspace?documentOf(workspace,'aiv'):undefined;const valveDocument=()=>workspace?documentOf(workspace,'valves'):undefined;
</script>

<header><div class="brand"><span class="mark">M3</span><div><h1>Mech Reader Studio</h1><small>AI · Behavior Graph · Valve Logic · Networks & Regions</small></div></div><div class="actions"><button onclick={chooseRoot}>Choose MW3 folder</button><button onclick={openDirect}>Open file…</button>{#if workspace&&workspace.sessionId!==0}<button onclick={attachReader}>Attach Reader…</button>{/if}<button class="primary" disabled={!workspace||busy} onclick={exportChanges}>{workspace?.sessionId===0?'Save As…':'Export changes…'}</button></div></header>
<div class="status"><span class:working={busy}>{busy?'Working…':message}</span>{#if workspace}<code>{workspace.selectedMission}</code>{/if}</div>
<main class:without-library={!library} class:mission-collapsed={library&&missionCollapsed}>
  {#if library}<aside class:collapsed={missionCollapsed} class="mission-sidebar">{#if missionCollapsed}<button class="sidebar-expander" aria-label="Expand mission overview" title="Expand mission overview" onclick={toggleMissionSidebar}>›<span>Missions</span></button>{:else}<div class="side-heading"><div><small>GAME LIBRARY</small><b>Missions</b></div><div class="side-heading-actions"><span class="count">{library.missions.length}</span><button aria-label="Collapse mission overview" title="Collapse mission overview" onclick={toggleMissionSidebar}>‹</button></div></div><div class="mission-list">{#each library.missions as mission}<button class:active={missionActive(mission)} onclick={()=>openMission(mission)}><div><b>{mission.name}</b><small>{mission.kind} · {mission.relativePath}</small></div><div class="mission-meta"><span>{mission.vehicleCount} AI</span><span>{mission.networkCount} nets</span><span>{mission.regionCount} regions</span></div></button>{/each}</div>{#if workspace}<div class="layers"><h4>Loaded Reader layers</h4>{#each workspace.archives as archive}<div><span><b>{archive.layer}</b><small>{archive.relativePath}</small></span>{#if archive.locked}<button onclick={()=>unlock(archive.id)}>Unlock</button>{:else}<em>editable</em>{/if}</div>{/each}</div>{/if}{/if}</aside>{/if}
  <section class="application">
    {#if workspace}
      <nav class="module-nav"><button class:active={mode==='ai'} onclick={()=>mode='ai'}><span>AI Vehicles</span><small>aiv.zrd</small></button><button class:active={mode==='behavior'} onclick={()=>mode='behavior'}><span>Behavior Graph</span><small>{workspace.valveGraph.channels.length} channels</small></button><button class:active={mode==='animations'} onclick={()=>mode='animations'}><span>Animations</span><small>anim.zbd</small></button><button class:active={mode==='valves'} onclick={()=>mode='valves'}><span>Valve Logic</span><small>valves.zrd</small></button><button class:active={mode==='networks'} onclick={()=>mode='networks'}><span>Networks & Regions</span><small>net_ / reg_</small></button><button class:active={mode==='references'} onclick={()=>mode='references'}><span>References</span><small>{workspace.references.length} links</small></button>{#if workspace.diagnostics.length||workspace.valveGraph.diagnostics.some(item=>item.severity!=='info')}<span class="diagnostic-count">{workspace.diagnostics.length+workspace.valveGraph.diagnostics.filter(item=>item.severity!=='info').length} warning{workspace.diagnostics.length+workspace.valveGraph.diagnostics.filter(item=>item.severity!=='info').length===1?'':'s'}</span>{/if}</nav>
      <div class="module-content">{#if mode==='ai'}{#if aiDocument()}<AiEditor workspace={workspace} document={aiDocument()!} layout={aiLayout} onChanged={changed} onNavigate={navigate}/>{:else}<div class="empty-state"><h2>No aiv.zrd in the loaded layers</h2><p>This Reader can still be inspected through Behavior Graph, Valve Logic, networks, regions, and references.</p></div>{/if}{:else if mode==='behavior'}{#if workspace.sessionId!==0}<BehaviorGraph workspace={workspace} onWorkspace={graphWorkspace} onUnlock={unlock} onNavigate={navigateGraph}/>{:else}<div class="empty-state"><h2>Open a Reader workspace for Behavior Graph</h2><p>The graph edits existing records across loaded Reader archives and is unavailable for standalone aiv.zrd files.</p></div>{/if}{:else if mode==='valves'}{#if valveDocument()}<ValveEditor workspace={workspace} document={valveDocument()!} onChanged={changed}/>{:else}<div class="empty-state"><h2>No valves.zrd</h2><p>No Valve action document is present in the loaded layers. VList channels remain valid global state names.</p></div>{/if}{:else if mode==='animations'}{#if workspace.sessionId!==0}<AnimationGraph workspace={workspace}/>{:else}<div class="empty-state"><h2>Open a game folder for Animations</h2><p>The animation graph reads the campaign's anim.zbd next to the mission Reader.</p></div>{/if}{:else if mode==='networks'}{#key `${networkFocus}:${workspace.sessionId}`}<NetworkEditor workspace={workspace} onChanged={changed} focusName={networkFocus}/>{/key}{:else}<ReferenceBrowser workspace={workspace} onChanged={changed}/>{/if}</div>
    {:else if library}<div class="welcome"><span class="mark large">M3</span><h2>Select a mission Reader</h2><p>The mission will be opened together with its campaign and global base layers.</p></div>{:else}<div class="welcome"><span class="mark large">M3</span><h2>Build a Reader workspace</h2><p>Choose the MechWarrior 3 folder to browse every mission, or open a Reader/ZRD file directly.</p><div class="welcome-actions">{#if lastRoot}<button class="primary" onclick={()=>loadRoot(lastRoot)}>Reopen last folder</button>{/if}<button class:primary={!lastRoot} onclick={chooseRoot}>Choose MW3 folder</button><button onclick={openDirect}>Open file…</button></div>{#if lastRoot}<code class="last-root">{lastRoot}</code>{/if}</div>{/if}
  </section>
</main>
